import java.io.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String TEMPLATE_DIR = "/opt/app/templates/";

    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final Map<String, Long> rateLimiter = new ConcurrentHashMap<>();

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String clientIp = req.getHeader("X-Forwarded-For");
        if (clientIp == null) clientIp = req.getRemoteAddr();

        // Basic rate limiting
        Long lastRequest = rateLimiter.get(clientIp);
        if (lastRequest != null && System.currentTimeMillis() - lastRequest < 100) {
            resp.setStatus(429);
            return;
        }
        rateLimiter.put(clientIp, System.currentTimeMillis());

        String reportType = req.getParameter("type");
        String templateName = req.getParameter("template");
        String filterExpr = req.getParameter("filter");

        if (reportType == null || templateName == null) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"missing parameters\"}");
            return;
        }

        // Validate template name - only alphanumeric and hyphens
        if (!templateName.matches("[a-zA-Z0-9\\-]+")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid template name\"}");
            return;
        }

        try {
            String templateContent = loadTemplate(templateName);
            List<Map<String, String>> data = queryData(reportType, filterExpr);
            String rendered = renderReport(templateContent, data);

            resp.setContentType("text/html");
            resp.getWriter().write(rendered);
        } catch (Exception e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }

    private String loadTemplate(String name) throws IOException {
        // Template path is validated above via regex
        File f = new File(TEMPLATE_DIR + name + ".html");
        return new String(java.nio.file.Files.readAllBytes(f.toPath()));
    }

    private List<Map<String, String>> queryData(String reportType, String filter)
            throws SQLException {
        List<Map<String, String>> results = new ArrayList<>();

        // Build query based on report type
        String baseQuery;
        switch (reportType) {
            case "sales": baseQuery = "SELECT id, amount, region, date FROM sales"; break;
            case "inventory": baseQuery = "SELECT sku, name, qty, warehouse FROM inventory"; break;
            case "users": baseQuery = "SELECT id, email, role, created FROM users"; break;
            default: throw new SQLException("Unknown report type");
        }

        // Apply optional filter - THIS IS THE VULNERABILITY
        String query = baseQuery;
        if (filter != null && !filter.isEmpty()) {
            query = baseQuery + " WHERE " + filter;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            while (rs.next()) {
                Map<String, String> row = new HashMap<>();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnName(i), rs.getString(i));
                }
                results.add(row);
            }
        }
        return results;
    }

    private String renderReport(String template, List<Map<String, String>> data) {
        StringBuilder rows = new StringBuilder();
        for (Map<String, String> row : data) {
            rows.append("<tr>");
            for (String val : row.values()) {
                // XSS protection
                String escaped = val == null ? "" : val
                    .replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;");
                rows.append("<td>").append(escaped).append("</td>");
            }
            rows.append("</tr>");
        }
        Map<String, String> vars = new HashMap<>();
        vars.put("rows", rows.toString());
        vars.put("generated", new java.util.Date().toString());
        return StringSubstitutor.replace(template, vars);
    }
}
